local config = {
  str_homestory_N23paixi_90040101_1_dialog_content = "Vice, about what you told me yesterday...",
  str_homestory_N23paixi_90040101_2_dialog_content = "I slept on it and I think it's really doable!",
  str_homestory_N23paixi_90040101_3_dialog_content = "Heheh, I knew you'd get me, PlayerName!",
  str_homestory_N23paixi_90040101_4_dialog_content = "I know I already keep a journal every day...",
  str_homestory_N23paixi_90040101_5_dialog_content = "but I still think it'd be better to document our experiences on video.",
  str_homestory_N23paixi_90040101_6_dialog_content = "Yeah, we've been through the most interesting things together.",
  str_homestory_N23paixi_90040101_7_dialog_content = "Exactly!",
  str_homestory_N23paixi_90040101_8_dialog_content = "If we could film them in an artistic form like a <color=#FFB400>movie</color>, that would be amazing.",
  str_homestory_N23paixi_90040101_9_dialog_content = "Hmm. That's right!",
  str_homestory_N23paixi_90040101_10_dialog_content = "Hmm, on that note...",
  str_homestory_N23paixi_90040101_11_dialog_content = "If we want to make a movie, we need to make a <color=#FFB400>movie studio</color> first, right?",
  str_homestory_N23paixi_90040101_12_dialog_content = "I guess so.",
  str_homestory_N23paixi_90040101_13_dialog_content = "Think I can leave the architectural blueprints and stuff to you, Vice.",
  str_homestory_N23paixi_90040101_14_dialog_content = "I know you're good at those things.",
  str_homestory_N23paixi_90040101_15_dialog_content = "Huh? Well, I do know how to design blueprints and stuff...",
  str_homestory_N23paixi_90040101_16_dialog_content = "But I don't know anything about filmmaking equipment.",
  str_homestory_N23paixi_90040101_17_dialog_content = "W-What?!",
  str_homestory_N23paixi_90040101_18_dialog_content = "There are blueprints even you can't design?",
  str_homestory_N23paixi_90040101_19_dialog_content = "H-Hey! Is that supposed to be a compliment or an insult?",
  str_homestory_N23paixi_90040101_20_dialog_content = "I'm just shocked.",
  str_homestory_N23paixi_90040101_21_dialog_content = "Hmm... Movies, a movie studio... filmmaking equipment, a producer...",
  str_homestory_N23paixi_90040101_22_dialog_content = "Producer?",
  str_homestory_N23paixi_90040101_23_dialog_content = "Right! Producer!",
  str_homestory_N23paixi_90040101_24_dialog_content = "PlayerName, why don't we ask <color=#FFB400>Minos</color>?",
  str_homestory_N23paixi_90040101_25_dialog_content = "I mean, he has recent experience. We can totally ask him to help!",
  str_homestory_N23paixi_90040101_26_dialog_content = "You're right!",
  str_homestory_N23paixi_90040101_27_dialog_content = "Let's go ask him.",
  str_homestory_N23paixi_90040102_1_dialog_content = "Hey, Minos!",
  str_homestory_N23paixi_90040102_2_dialog_content = "Good afternoon, honorable PlayerName.",
  str_homestory_N23paixi_90040102_3_dialog_content = "I happen to have a question to ask you, if you don't mind, of course.",
  str_homestory_N23paixi_90040102_4_dialog_content = "Sure. I'm glad to be of any help I can be.",
  str_homestory_N23paixi_90040102_5_dialog_content = "Right.",
  str_homestory_N23paixi_90040102_6_dialog_content = "Miss Nina's dietary preferences have recently changed. She's really into <color=#FFB400>fish</color> now.",
  str_homestory_N23paixi_90040102_7_dialog_content = "Now, normally I should be the one preparing her meals, as I am her butler.",
  str_homestory_N23paixi_90040102_8_dialog_content = "But, right now, I'm trying to review and record my experience being a producer.",
  str_homestory_N23paixi_90040102_9_dialog_content = "Rather than distracting myself and moving on to something else halfway through, I hope I can finish my review first.",
  str_homestory_N23paixi_90040102_10_dialog_content = "But if I do that, it'll definitely be past lunchtime by the time I get back with a fish to cook.",
  str_homestory_N23paixi_90040102_11_dialog_content = "I see. So you want me to <color=#FFB400>catch a few fish</color> for you, right?",
  str_homestory_N23paixi_90040102_12_dialog_content = "That's correct. I'd be grateful if you could spare some time to do that for me right now, PlayerName.",
  str_homestory_N23paixi_90040102_13_dialog_content = "Of course! You can count on me!",
  str_homestory_N23paixi_90040102_X13_dialog_content = "Ah, I almost forgot to ask.",
  str_homestory_N23paixi_90040102_X14_dialog_content = "What kind of fish do you need?",
  str_homestory_N23paixi_90040102_X15_dialog_content = "Apologies, I should have told you.",
  str_homestory_N23paixi_90040102_X16_dialog_content = "Lately, Miss Nina has been enjoying Knifefish.",
  str_homestory_N23paixi_90040102_X17_dialog_content = "Alright, I got it! Leave it to me.",
  str_homestory_N23paixi_90040102_14_dialog_content = "By the way, what do you mean by \"review\"?",
  str_homestory_N23paixi_90040102_15_dialog_content = "I want to make a comprehensive record of my recent experience being a producer.",
  str_homestory_N23paixi_90040102_16_dialog_content = "For example, how a set is built, what is required of the crew to make a movie, and how to operate the necessary equipment.",
  str_homestory_N23paixi_90040102_17_dialog_content = "Of course, it's not because I'm some movie fanatic that I'm doing this.",
  str_homestory_N23paixi_90040102_18_dialog_content = "I just want to be prepared if Miss Nina is suddenly interested in it someday.<sprite=emo_mojing size=60 />",
  str_homestory_N23paixi_90040102_19_dialog_content = "I see.",
  str_homestory_N23paixi_90040102_20_dialog_content = "Actually, I'm in need of that \"review\" of yours. That's why I'm here.",
  str_homestory_N23paixi_90040102_21_dialog_content = "After I come back with your fish, can you please tell me what goes into making a film?",
  str_homestory_N23paixi_90040102_22_dialog_content = "Of course. I'd be glad to help.",
  str_homestory_N23paixi_90040102_23_dialog_content = "I shall be waiting for your return, then.",
  str_homestory_N23paixi_90040103_1_dialog_content = "That was a lot faster than I expected.",
  str_homestory_N23paixi_90040103_2_dialog_content = "Of course! ({1}/{2})",
  str_homestory_N23paixi_90040103_5_dialog_content = "Thank you. I'll repay you with what you need of me.",
  str_homestory_N23paixi_90040103_6_dialog_content = "I've completed my review.",
  str_homestory_N23paixi_90040103_7_dialog_content = "Now, let me confirm what you want from me...",
  str_homestory_N23paixi_90040103_8_dialog_content = "You want to make a movie studio in Cloud Gardens, yes?",
  str_homestory_N23paixi_90040103_9_dialog_content = "That's right.",
  str_homestory_N23paixi_90040103_10_dialog_content = "But I really don't know what kind of equipment we'll need...",
  str_homestory_N23paixi_90040103_11_dialog_content = "I see.",
  str_homestory_N23paixi_90040103_12_dialog_content = "Earlier, I managed to compile a list of all the things you'll need to make a movie studio.",
  str_homestory_N23paixi_90040103_13_dialog_content = "I can provide you with most equipment and building materials directly.",
  str_homestory_N23paixi_90040103_14_dialog_content = "Ahem, this is of course because the Andersens hold you in high regard.",
  str_homestory_N23paixi_90040103_15_dialog_content = "However, I still need some materials to make the <color=#FFB400>backdrops</color>.",
  str_homestory_N23paixi_90040103_16_dialog_content = "Backdrops are also necessary for making films, right?",
  str_homestory_N23paixi_90040103_17_dialog_content = "That's correct.",
  str_homestory_N23paixi_90040103_18_dialog_content = "Ah, so you need me to gather some materials for you!",
  str_homestory_N23paixi_90040103_19_dialog_content = "Yes. I'll need you to gather <color=#FFB400>10 wood</color> for me.",
  str_homestory_N23paixi_90040103_20_dialog_content = "Once I have the wood, I can begin making the backdrops.",
  str_homestory_N23paixi_90040103_21_dialog_content = "I'll also have other things prepared for you.",
  str_homestory_N23paixi_90040103_22_dialog_content = "That's... amazing! Thanks, Minos!",
  str_homestory_N23paixi_90040103_23_dialog_content = "I'll get to it, then!",
  str_homestory_N23paixi_90040103_24_dialog_content = "Much appreciated, PlayerName.",
  str_homestory_N23paixi_90040103_3_dialog_content = "I've still got a bit more to catch...",
  str_homestory_N23paixi_90040103_4_dialog_content = "Thank you for all the hard work, PlayerName.",
  str_homestory_N23paixi_90040104_1_dialog_content = "That was a lot faster than I expected.",
  str_homestory_N23paixi_90040104_2_dialog_content = "Of course! ({1}/{2})",
  str_homestory_N23paixi_90040104_5_dialog_content = "I've prepared everything that you'll need right here.",
  str_homestory_N23paixi_90040104_6_dialog_content = "I'll need some time to polish up these future backdrops...",
  str_homestory_N23paixi_90040104_7_dialog_content = "You'll be able to see them soon, and everything else you'll need to make films.",
  str_homestory_N23paixi_90040104_8_dialog_content = "I'm so blessed to have a butler like you in Cloud Gardens, Minos!",
  str_homestory_N23paixi_90040104_9_dialog_content = "I'm honored that you think so.",
  str_homestory_N23paixi_90040104_3_dialog_content = "I still need a little more...",
  str_homestory_N23paixi_90040104_4_dialog_content = "Thank you for all your hard work, PlayerName.",
  str_homestory_N23paixi_90040105_1_dialog_content = "Minos, you're really amazing! Everything's done!",
  str_homestory_N23paixi_90040105_X1_dialog_content = "You flatter me.",
  str_homestory_N23paixi_90040105_2_dialog_content = "Now I have to figure out<sprite=emo_sikao size=60 /> where we should put our movie studio.",
  str_homestory_N23paixi_90040106_1_dialog_content = "Phew! Now that the location is set, my movie studio is really taking shape.",
  str_homestory_N23paixi_90040106_2_dialog_content = "But things here seem to need some cleaning and organizing.",
  str_homestory_N23paixi_90040106_3_dialog_content = "The movie studio should be up and running once everything's cleaned up.",
  str_homestory_N23paixi_90040107_1_dialog_content = "Minos! I just tested out the equipment...",
  str_homestory_N23paixi_90040107_2_dialog_content = "They're amazing!",
  str_homestory_N23paixi_90040107_3_dialog_content = "I'm happy to see you so thrilled.",
  str_homestory_N23paixi_90040107_4_dialog_content = "Actually, I have one more thing for you, if you'd be willing to take it.",
  str_homestory_N23paixi_90040107_5_dialog_content = "Here's a script that I received during my time as a producer.",
  str_homestory_N23paixi_90040107_6_dialog_content = "Now that you have a movie studio here, I think it may be of some use to you.",
  str_homestory_N23paixi_90040107_7_dialog_content = "Of course, you can turn me down if you already have something else in mind.",
  str_homestory_N23paixi_90040107_8_dialog_content = "Either way, I believe this script may still serve as a good template to reference.",
  str_homestory_N23paixi_90040107_9_dialog_content = "That's really useful!",
  str_homestory_N23paixi_90040107_10_dialog_content = "I promise to make good use of it, Minos!",
  str_homestory_N23paixi_90040107_11_dialog_content = "I... really don't know how to thank you.",
  str_homestory_N23paixi_90040107_12_dialog_content = "You're welcome, PlayerName.",
  str_homestory_N23paixi_90040107_13_dialog_content = "Are you gonna tell me that it's just another one of your expected duties?",
  str_homestory_N23paixi_90040107_14_dialog_content = "For once, just accept my thanks. Please?",
  str_homestory_N23paixi_90040107_15_dialog_content = "I mean, you really helped me out.",
  str_homestory_N23paixi_90040107_16_dialog_content = "I see. Fine, then.",
  str_homestory_N23paixi_90040107_17_dialog_content = "I'll take your gratitude to heart.",
  str_homestory_N23paixi_90040107_18_dialog_content = "That's what I'm talking about!",
  str_homestory_N23paixi_90040108_1_dialog_content = "Vice!",
  str_homestory_N23paixi_90040108_2_dialog_content = "Waaaah! I'm so happy! I see it, PlayerName!",
  str_homestory_N23paixi_90040108_3_dialog_content = "I can't believe you've set up the movie studio already!",
  str_homestory_N23paixi_90040108_4_dialog_content = "Ahaha. Even though I'm glad to be complimented by you...",
  str_homestory_N23paixi_90040108_5_dialog_content = "Minos actually did most of the work here.",
  str_homestory_N23paixi_90040108_6_dialog_content = "All I did was gather materials for him.",
  str_homestory_N23paixi_90040108_7_dialog_content = "Oh, I see...",
  str_homestory_N23paixi_90040108_8_dialog_content = "Do you think there's anything in the world that Minos can't do?",
  str_homestory_N23paixi_90040108_9_dialog_content = "Actually, I'm curious about that too.",
  str_homestory_N23paixi_90040108_10_dialog_content = "Anyway, I've thanked him dearly.",
  str_homestory_N23paixi_90040108_11_dialog_content = "Good.",
  str_homestory_N23paixi_90040108_12_dialog_content = "Now that the movie studio is good to go, let's try it out!",
  str_homestory_N23paixi_90040108_13_dialog_content = "You read my mind!",
  str_homestory_N23paixi_90040108_14_dialog_content = "Oh, and Minos happened to give me a <color=#FFB400>script</color>.",
  str_homestory_N23paixi_90040108_15_dialog_content = "Now let's give this thing a good study, shall we?",
  str_homestory_N23paixi_90040108_16_dialog_content = "Heheh. The thought of studying new machines fills me with excitement!",
  str_homestory_N23paixi_90040108_17_dialog_content = "They're not just machines, Vice... This is a form of art.",
  str_homestory_N23paixi_90040108_18_dialog_content = "I-I know!",
  str_homestory_N23paixi_90040201_1_dialog_content = "Hey, PlayerName!",
  str_homestory_N23paixi_90040201_2_dialog_content = "Hey, Lilica!",
  str_homestory_N23paixi_90040201_3_dialog_content = "Wooooow! I really gotta say—",
  str_homestory_N23paixi_90040201_4_dialog_content = "Cloud Gardens is sooooo impressive!",
  str_homestory_N23paixi_90040201_5_dialog_content = "I never would've thought that there'd even be a movie studio here!",
  str_homestory_N23paixi_90040201_6_dialog_content = "Not only that, but all the equipment looks so professional as well!",
  str_homestory_N23paixi_90040201_7_dialog_content = "You really are super considerate, like everyone says!",
  str_homestory_N23paixi_90040201_8_dialog_content = "I don't know how to thank you for taking care of the needs of movie enthusiasts like me! You're amazing!",
  str_homestory_N23paixi_90040201_9_dialog_content = "W-Wait a minute, Lilica.",
  str_homestory_N23paixi_90040201_10_dialog_content = "Minos actually provided most of the things you see in the studio.",
  str_homestory_N23paixi_90040201_11_dialog_content = "Huh? Him?",
  str_homestory_N23paixi_90040201_12_dialog_content = "Right. That explains a lot.",
  str_homestory_N23paixi_90040201_13_dialog_content = "I mean, only someone with relevant experience could make a studio like this.",
  str_homestory_N23paixi_90040201_14_dialog_content = "Yeah. Personally, I don't think making films is a simple thing.",
  str_homestory_N23paixi_90040201_15_dialog_content = "Just look over there...",
  str_homestory_N23paixi_90040201_16_dialog_content = "The sets and the backdrops are done.",
  str_homestory_N23paixi_90040201_17_dialog_content = "But I still don't know exactly how to operate the camera or find the right actors for the job.<sprite=emo_tanqi size=60 />",
  str_homestory_N23paixi_90040201_18_dialog_content = "Hmm, Is that so?",
  str_homestory_N23paixi_90040201_19_dialog_content = "Well, don't you worry, PlayerName. I can take care of finding the right actors for you.",
  str_homestory_N23paixi_90040201_20_dialog_content = "About the camera and stuff though... even if I do have some experience with them, I'm still pretty much a novice.",
  str_homestory_N23paixi_90040201_21_dialog_content = "PlayerName, why don't you ask the pretty girl over there who always has her nose in a book?",
  str_homestory_N23paixi_90040201_22_dialog_content = "I haven't been here long, but every time I see her...",
  str_homestory_N23paixi_90040201_23_dialog_content = "I mean EVERY SINGLE TIME, she's always reading.",
  str_homestory_N23paixi_90040201_24_dialog_content = "The girl you're talking about... has long, curly brown hair, right?",
  str_homestory_N23paixi_90040201_25_dialog_content = "Yup!",
  str_homestory_N23paixi_90040201_26_dialog_content = "She looks really smart!",
  str_homestory_N23paixi_90040201_27_dialog_content = "Well, it couldn't be anyone else.",
  str_homestory_N23paixi_90040201_28_dialog_content = "I guess I'll go and talk to <color=#FFB400>Hedy</color> right now, then.",
  str_homestory_N23paixi_90040201_29_dialog_content = "So her name is Hedy?",
  str_homestory_N23paixi_90040201_30_dialog_content = "I knew it. Pretty girls have pretty names too.",
  str_homestory_N23paixi_90040201_31_dialog_content = "I'll wait for your good news, then, PlayerName!",
  str_homestory_N23paixi_90040202_1_dialog_content = "Hmm? It's you.",
  str_homestory_N23paixi_90040202_2_dialog_content = "Hi.",
  str_homestory_N23paixi_90040202_3_dialog_content = "Hey, Hedy!",
  str_homestory_N23paixi_90040202_4_dialog_content = "What are you doing?",
  str_homestory_N23paixi_90040202_5_dialog_content = "Reading.",
  str_homestory_N23paixi_90040202_6_dialog_content = "Ah yes, you seem to do that a lot.",
  str_homestory_N23paixi_90040202_7_dialog_content = "But you chose to read here today instead of reading in your room.",
  str_homestory_N23paixi_90040202_8_dialog_content = "Are you trying to ask why I'm reading here?",
  str_homestory_N23paixi_90040202_9_dialog_content = "You're a keen observer, I'll give you that.",
  str_homestory_N23paixi_90040202_10_dialog_content = "To be honest, I've been reading books about fish recently.",
  str_homestory_N23paixi_90040202_11_dialog_content = "I wanted to investigate a <color=#FFB400>Snakeel</color> in person...",
  str_homestory_N23paixi_90040202_12_dialog_content = "But I don't know where you keep your fishing equipment.",
  str_homestory_N23paixi_90040202_13_dialog_content = "So I thought I'd just take a look around...",
  str_homestory_N23paixi_90040202_14_dialog_content = "Fishing equipment? You could've just asked me.",
  str_homestory_N23paixi_90040202_15_dialog_content = "Why would I ask someone to help me with something so trifle?",
  str_homestory_N23paixi_90040202_16_dialog_content = "Uhm... okay.",
  str_homestory_N23paixi_90040202_17_dialog_content = "Actually, we can skip all that.",
  str_homestory_N23paixi_90040202_18_dialog_content = "Why don't I just get a Snakeel for you to study? I mean, if you want me to, that is.",
  str_homestory_N23paixi_90040202_19_dialog_content = "I-I couldn't possibly trouble you like that...",
  str_homestory_N23paixi_90040202_20_dialog_content = "Don't worry, 'cause I also have something I need to ask you as well.",
  str_homestory_N23paixi_90040202_21_dialog_content = "Oh?",
  str_homestory_N23paixi_90040202_22_dialog_content = "... I see.",
  str_homestory_N23paixi_90040202_23_dialog_content = "I do indeed have some books on filmmaking.",
  str_homestory_N23paixi_90040202_24_dialog_content = "I'll get them for you in a bit if you need them.",
  str_homestory_N23paixi_90040202_25_dialog_content = "Actually... I'll go to my room and get them for you right now.",
  str_homestory_N23paixi_90040202_26_dialog_content = "That'd be great! Thanks, Hedy!",
  str_homestory_N23paixi_90040202_27_dialog_content = "My pleasure.",
  str_homestory_N23paixi_90040202_28_dialog_content = "We'll meet back here and trade, then.",
  str_homestory_N23paixi_90040202_29_dialog_content = "You got it!",
  str_homestory_N23paixi_90040203_1_dialog_content = "You got three Snakeels already?",
  str_homestory_N23paixi_90040203_2_dialog_content = "Got it! ({1}/{2})",
  str_homestory_N23paixi_90040203_5_dialog_content = "Thank you.",
  str_homestory_N23paixi_90040203_3_dialog_content = "I'm still working on it!",
  str_homestory_N23paixi_90040203_4_dialog_content = "I wish you luck.",
  str_homestory_N23paixi_90040204_1_dialog_content = "Here are the books that you wanted.",
  str_homestory_N23paixi_90040204_2_dialog_content = "I leafed through them briefly. The one I recommend most is <color=#FFB400>30 Lessons On Running a Movie Studio</color>.",
  str_homestory_N23paixi_90040204_3_dialog_content = "It not only discusses theories, but also teaches you how to apply them using real examples.",
  str_homestory_N23paixi_90040204_4_dialog_content = "The author used to work as a film crew member, so they also offered solutions to many common problems.",
  str_homestory_N23paixi_90040204_5_dialog_content = "Overall, I think this book will really help you out.",
  str_homestory_N23paixi_90040204_6_dialog_content = "I see! You're very considerate, Hedy.",
  str_homestory_N23paixi_90040204_7_dialog_content = "I'll be sure to carefully study every word of this book!",
  str_homestory_N23paixi_90040204_8_dialog_content = "Ahem, h-how you read the book has nothing to do with me!<sprite=emo_baimao size=60 />",
  str_homestory_N23paixi_90040204_9_dialog_content = "Anyway, thank you so much!",
  str_homestory_N23paixi_90040204_10_dialog_content = "My pleasure.",
  str_homestory_N23paixi_90040205_1_dialog_content = "Oh, wow! 30 Lessons On Running a Movie Studio!?",
  str_homestory_N23paixi_90040205_2_dialog_content = "Waaah! You and Hedy are wonderful!",
  str_homestory_N23paixi_90040205_3_dialog_content = "It looks like a great read!",
  str_homestory_N23paixi_90040205_4_dialog_content = "Especially for me!",
  str_homestory_N23paixi_90040205_5_dialog_content = "Now that we have this book, if I don't manage to become a real actor in the future, at least I can still work among the crew!",
  str_homestory_N23paixi_90040205_6_dialog_content = "Wow Lilica, that's very... pragmatic of you!",
  str_homestory_N23paixi_90040205_7_dialog_content = "Of course! That's how I got to where I am today.",
  str_homestory_N23paixi_90040205_8_dialog_content = "Alright. Now we have everything we need to make a film...",
  str_homestory_N23paixi_90040205_9_dialog_content = "and also our first script, plus a book full of solutions for emergency situations!",
  str_homestory_N23paixi_90040205_10_dialog_content = "Right. So we can begin making films, right?",
  str_homestory_N23paixi_90040205_11_dialog_content = "Give me time to go through this book first!",
  str_homestory_N23paixi_90040205_12_dialog_content = "I still have to learn how to operate the equipment!",
  str_homestory_N23paixi_90040205_13_dialog_content = "Right. I'll read it with you, then.",
  str_homestory_N23paixi_90040301_1_dialog_content = "Heheh, PlayerName! I have good news for you.",
  str_homestory_N23paixi_90040301_2_dialog_content = "Our movie studio is fully in operation!",
  str_homestory_N23paixi_90040301_3_dialog_content = "You know all the equipment we knocked around so much? They aren't broken at all!",
  str_homestory_N23paixi_90040301_4_dialog_content = "Not only that, I've already made a few shorts with them!",
  str_homestory_N23paixi_90040301_5_dialog_content = "The equipment really is of good quality, heheh.<sprite=emo_guilian size=60 />",
  str_homestory_N23paixi_90040301_6_dialog_content = "Ahahaha... About that... I think we need to be more gentle with the equipment sometimes.",
  str_homestory_N23paixi_90040301_7_dialog_content = "Yeah, you're right.",
  str_homestory_N23paixi_90040301_8_dialog_content = "But I'm here to talk business with you.",
  str_homestory_N23paixi_90040301_9_dialog_content = "Many Aurorians have seen the studio.",
  str_homestory_N23paixi_90040301_10_dialog_content = "They told me that they also want to make their own films and try making their own ideas come to life.",
  str_homestory_N23paixi_90040301_11_dialog_content = "But since I'm not the boss here, I thought I should ask for your opinion.",
  str_homestory_N23paixi_90040301_12_dialog_content = "Of course. No problem.",
  str_homestory_N23paixi_90040301_13_dialog_content = "Yes! I knew you'd say okay!",
  str_homestory_N23paixi_90040301_14_dialog_content = "But, Lilica...",
  str_homestory_N23paixi_90040301_15_dialog_content = "If we wait until everyone has a chance to get familiar with the equipment before we start making films... Wouldn't that be wasting a lot of time?",
  str_homestory_N23paixi_90040301_16_dialog_content = "Heheh, don't you worry.",
  str_homestory_N23paixi_90040301_17_dialog_content = "The one wielding the camera shall be none other than yours truly, Lilica the up-and-coming director!",
  str_homestory_N23paixi_90040301_18_dialog_content = "By helping everyone fulfill their wishes of making their own movies, I'll also be able to get lots of hands-on shooting experience!",
  str_homestory_N23paixi_90040301_19_dialog_content = "It's a win-win situation whichever way you look at it.",
  str_homestory_N23paixi_90040301_20_dialog_content = "So, don't worry about the technical issues!",
  str_homestory_N23paixi_90040301_21_dialog_content = "Alright then.",
  str_homestory_N23paixi_90040301_22_dialog_content = "I do trust your professionalism, Lilica.",
  str_homestory_N23paixi_90040301_23_dialog_content = "Very good!",
  str_homestory_N23paixi_90040301_24_dialog_content = "Now, we should get going and start helping our very first client!",
  str_homestory_N23paixi_90040301_25_dialog_content = "Our first client?",
  str_homestory_N23paixi_90040301_26_dialog_content = "That's right!",
  str_homestory_N23paixi_90040301_27_dialog_content = "Sadie is waiting for you at <color=#FFB400>Hyacinth Square</color>!",
  str_homestory_N23paixi_90040301_28_dialog_content = "Huh? Why me?",
  str_homestory_N23paixi_90040301_29_dialog_content = "Because I have to stay here and get familiar with the equipment!",
  str_homestory_N23paixi_90040301_30_dialog_content = "And you know everyone here more than I do, don't you?",
  str_homestory_N23paixi_90040301_31_dialog_content = "Right... Okay. I'll see you later, then.",
  str_homestory_N23paixi_90040301_32_dialog_content = "I'll be waiting right here.",
  str_homestory_N23paixi_90040302_1_dialog_content = "You're finally here, PlayerName. I've been anticipating you.",
  str_homestory_N23paixi_90040302_2_dialog_content = "Hey, Sadie!",
  str_homestory_N23paixi_90040302_3_dialog_content = "Lilica told me you want to make a film about swashbucklers, right?",
  str_homestory_N23paixi_90040302_4_dialog_content = "That's right!",
  str_homestory_N23paixi_90040302_5_dialog_content = "I have ideas, but no concrete plan.",
  str_homestory_N23paixi_90040302_6_dialog_content = "There are many cool girls here, but I'm not one of them.",
  str_homestory_N23paixi_90040302_7_dialog_content = "But this doesn't change the fact that I want to make a real swashbuckler movie!",
  str_homestory_N23paixi_90040302_8_dialog_content = "Uhm... Why don't you tell me about your idea first?",
  str_homestory_N23paixi_90040302_9_dialog_content = "Then we'll see if we can make it happen.",
  str_homestory_N23paixi_90040302_10_dialog_content = "First, I want it to take place at night. A very dark night.",
  str_homestory_N23paixi_90040302_11_dialog_content = "Second, I want there to be many enemies on guard.",
  str_homestory_N23paixi_90040302_12_dialog_content = "Third, I want you to ask the cool girls something for me.",
  str_homestory_N23paixi_90040302_13_dialog_content = "Every time I try to ask them myself, they panic and hide.",
  str_homestory_N23paixi_90040302_14_dialog_content = "They're always worried that I'll run into danger and end up kidnapped or something.",
  str_homestory_N23paixi_90040302_15_dialog_content = "Uhm... So who do you want me to ask?",
  str_homestory_N23paixi_90040302_16_dialog_content = "Allura! Allura!",
  str_homestory_N23paixi_90040302_17_dialog_content = "Okay.",
  str_homestory_N23paixi_90040302_18_dialog_content = "You just want me to ask her what a day in her life is like as a mature and cool mercenary, right?",
  str_homestory_N23paixi_90040302_19_dialog_content = "Yes, yes, yes!",
  str_homestory_N23paixi_90040302_20_dialog_content = "You stay here. I'll be right back.",
  str_homestory_N23paixi_90040302_21_dialog_content = "You rock.<sprite=emo_dianzan size=60 />",
  str_homestory_N23paixi_90040303_1_dialog_content = "Did you need something?",
  str_homestory_N23paixi_90040303_2_dialog_content = "Ah, um... Ahem!",
  str_homestory_N23paixi_90040303_3_dialog_content = "I just wanted to know how you were settling in, Allura.",
  str_homestory_N23paixi_90040303_4_dialog_content = "As long as I can take on jobs, where I live doesn't really matter.",
  str_homestory_N23paixi_90040303_5_dialog_content = "Right! Jobs!",
  str_homestory_N23paixi_90040303_6_dialog_content = "Uhm...?",
  str_homestory_N23paixi_90040303_7_dialog_content = "Right. So, what's your day like as a mature and cool mercenary?",
  str_homestory_N23paixi_90040303_8_dialog_content = "Are you trying to get me to do something for you for free?",
  str_homestory_N23paixi_90040303_9_dialog_content = "Is that why you're trying to flatter me?",
  str_homestory_N23paixi_90040303_10_dialog_content = "No! I'm just curious. That's all! Hahah.",
  str_homestory_N23paixi_90040303_11_dialog_content = "Depends on the job.",
  str_homestory_N23paixi_90040303_12_dialog_content = "If it's a high-risk job, then I do my homework and gather all the intel I can before starting.",
  str_homestory_N23paixi_90040303_13_dialog_content = "As for the usual run-of-the-mill jobs, I try to complete them as fast as I can so I can move on to another one.",
  str_homestory_N23paixi_90040303_14_dialog_content = "I can say for certain that the experience accumulated from all those small daily jobs are crucial to the success of the higher risk jobs.",
  str_homestory_N23paixi_90040303_15_dialog_content = "They train you in marksmanship and physical combat, and also prepare you for maintaining good relationships with your clients.",
  str_homestory_N23paixi_90040303_16_dialog_content = "Right!",
  str_homestory_N23paixi_90040303_17_dialog_content = "Gather... intel... completing jobs with haste...",
  str_homestory_N23paixi_90040303_18_dialog_content = "Okay. I got it. Thanks, Allura!",
  str_homestory_N23paixi_90040303_19_dialog_content = "Thanks so much for sharing!",
  str_homestory_N23paixi_90040303_20_dialog_content = "Thank you for thanking me.",
  str_homestory_N23paixi_90040303_21_dialog_content = "Now, pay up.",
  str_homestory_N23paixi_90040303_22_dialog_content = "I knew it!",
  str_homestory_N23paixi_90040304_1_dialog_content = "Daily training, no procrastinating, intel gathering, and job analysis!",
  str_homestory_N23paixi_90040304_2_dialog_content = "A full-fledged assault in the dark of night!",
  str_homestory_N23paixi_90040304_3_dialog_content = "Thank you, PlayerName!",
  str_homestory_N23paixi_90040304_4_dialog_content = "I now know what kind of movie I want to make.",
  str_homestory_N23paixi_90040304_5_dialog_content = "I just need to add a few more things to make my script perfect!",
  str_homestory_N23paixi_90040304_6_dialog_content = "You'll receive my completed script soon!",
  str_homestory_N23paixi_90040304_7_dialog_content = "Thank you sooooooo much! Thank you, thank you, thank you, thank you!",
  str_homestory_N23paixi_90040304_8_dialog_content = "Alright, alright. You don't have to say it so many times.",
  str_homestory_N23paixi_90040304_9_dialog_content = "Heheh.",
  str_homestory_N23paixi_90040304_10_dialog_content = "You rock, PlayerName!<sprite=emo_dianzan size=60 />",
  str_homestory_N23paixi_90040305_1_dialog_content = "So, how did it go? Did you get an answer?",
  str_homestory_N23paixi_90040305_2_dialog_content = "Yeah. Now I know how a cool mercenary supposedly spends their day.",
  str_homestory_N23paixi_90040305_3_dialog_content = "Heehee, that's great.",
  str_homestory_N23paixi_90040305_4_dialog_content = "Now our script will be even better!",
  str_homestory_N23paixi_90040305_5_dialog_content = "Not only did we get a great answer, but we can also give the film a special Sadie twist!",
  str_homestory_N23paixi_90040305_6_dialog_content = "I guess you could put it that way, but I wonder how the movie based on this script will turn out...",
  str_homestory_N23paixi_90040305_7_dialog_content = "I can't help but feel concerned.",
  str_homestory_N23paixi_90040305_8_dialog_content = "Well, this is how I think of things like this.",
  str_homestory_N23paixi_90040305_9_dialog_content = "Sure, we're all rookies here, but all the \"pros\" were also rookies once. They've gotten to where they are now by learning along the way, right?",
  str_homestory_N23paixi_90040305_10_dialog_content = "So what if this movie turns out bad? We'll learn from our mistakes and be better the next time!",
  str_homestory_N23paixi_90040305_11_dialog_content = "You're so right, Lilica! Now I feel excited!",
  str_homestory_N23paixi_90040305_12_dialog_content = "Then, let's get moving!",
  str_homestory_N23paixi_90040305_13_dialog_content = "Got it!",
  str_homestory_N23paixi_90040401_1_dialog_content = "PlayerName...",
  str_homestory_N23paixi_90040401_2_dialog_content = "What's wrong, Lilica?",
  str_homestory_N23paixi_90040401_3_dialog_content = "You seem a bit upset.",
  str_homestory_N23paixi_90040401_4_dialog_content = "I'm worried about the props that we'll need for the movie.",
  str_homestory_N23paixi_90040401_5_dialog_content = "You mean the props for \"The Swashbuckler\"?",
  str_homestory_N23paixi_90040401_6_dialog_content = "Exactly!",
  str_homestory_N23paixi_90040401_7_dialog_content = "Sadie demanded that this scene must be \"touching,\" so all the budget is going into it!",
  str_homestory_N23paixi_90040401_8_dialog_content = "But judging by the quality of the props that we have...",
  str_homestory_N23paixi_90040401_9_dialog_content = "They're not up to her standards, are they?",
  str_homestory_N23paixi_90040401_10_dialog_content = "Not only her standards. They don't even meet my own.",
  str_homestory_N23paixi_90040401_11_dialog_content = "Should I... ask her about this?",
  str_homestory_N23paixi_90040401_12_dialog_content = "I mean, most of her demands tend to be abstract and not actually concrete.<sprite=emo_baiyan size=60 />",
  str_homestory_N23paixi_90040401_13_dialog_content = "That'd be great!",
  str_homestory_N23paixi_90040401_14_dialog_content = "Thank you in advance, PlayerName.",
  str_homestory_N23paixi_90040401_15_dialog_content = "No problem.",
  str_homestory_N23paixi_90040402_1_dialog_content = "Oh...!",
  str_homestory_N23paixi_90040402_2_dialog_content = "So, you just need me to tell you exactly what props I have in mind?",
  str_homestory_N23paixi_90040402_3_dialog_content = "Yeah. Try to be detailed and specific.",
  str_homestory_N23paixi_90040402_4_dialog_content = "In this scene, the swashbuckler looks into a <color=#FFB400>mirror</color> and expresses her concerns and predicament.",
  str_homestory_N23paixi_90040402_5_dialog_content = "And then comes the climax of the movie— the swashbuckler transforms!<sprite=emo_nuhuo size=60 />",
  str_homestory_N23paixi_90040402_6_dialog_content = "The mirror suddenly emits a radiant, rainbow light, and shiny golden stars and pink hearts appear all around it!",
  str_homestory_N23paixi_90040402_7_dialog_content = "It's best if we can rotate the camera 360 degrees around the swashbuckler, with a close-up of the swashbuckler to show she's all grown up!",
  str_homestory_N23paixi_90040402_8_dialog_content = "Yeah, yeah! And as soon as she decides what to do, she gets this mysterious magic power that turns her into a beautiful, strong woman!",
  str_homestory_N23paixi_90040402_9_dialog_content = "... Isn't this what they call a magical girl transformation? The kind of thing that only happens in children's fantasy comics?",
  str_homestory_N23paixi_90040402_10_dialog_content = "T-That won't do?",
  str_homestory_N23paixi_90040402_11_dialog_content = "I... I mean, it's not undoable.",
  str_homestory_N23paixi_90040402_12_dialog_content = "Anyway, so all you need is that mirror with the magical powers, right?",
  str_homestory_N23paixi_90040402_13_dialog_content = "That's right.",
  str_homestory_N23paixi_90040402_14_dialog_content = "Well, in that case... we can probably make the mirror's frame out of wood.",
  str_homestory_N23paixi_90040402_15_dialog_content = "Yup!",
  str_homestory_N23paixi_90040402_16_dialog_content = "Hmm, alright.",
  str_homestory_N23paixi_90040402_17_dialog_content = "Anyway, I'll go <color=#FFB400>gather some wood</color> first...",
  str_homestory_N23paixi_90040402_18_dialog_content = "Making the frame of a mirror seems to be easy enough.",
  str_homestory_N23paixi_90040402_19_dialog_content = "Yup!",
  str_homestory_N23paixi_90040402_20_dialog_content = "Oh, I shouldn't have said that.",
  str_homestory_N23paixi_90040402_21_dialog_content = "I should say: Thank you, PlayerName!",
  str_homestory_N23paixi_90040402_22_dialog_content = "Just bring me the wood. I can make the frame myself!",
  str_homestory_N23paixi_90040402_23_dialog_content = "Okay.",
  str_homestory_N23paixi_90040403_1_dialog_content = "You're so fast, PlayerName.",
  str_homestory_N23paixi_90040403_2_dialog_content = "All done. ({1}/{2})",
  str_homestory_N23paixi_90040403_5_dialog_content = "Wow! You are so cool, PlayerName!",
  str_homestory_N23paixi_90040403_6_dialog_content = "Can you really make the mirror out of wood?",
  str_homestory_N23paixi_90040403_7_dialog_content = "Do you need my help?",
  str_homestory_N23paixi_90040403_8_dialog_content = "Have some faith in me. I can do it.",
  str_homestory_N23paixi_90040403_9_dialog_content = "I think we're gonna need some ore.",
  str_homestory_N23paixi_90040403_10_dialog_content = "Right... You can only make the basic frame out of wood.",
  str_homestory_N23paixi_90040403_11_dialog_content = "We'll need <color=#FFB400>ore</color> to make the actual mirror.",
  str_homestory_N23paixi_90040403_12_dialog_content = "Bingo!",
  str_homestory_N23paixi_90040403_13_dialog_content = "Alright. I'll go <color=#FFB400>gather some ore</color>, then.",
  str_homestory_N23paixi_90040403_14_dialog_content = "No need to push yourself, you hear? We can make the mirror together when I get back.",
  str_homestory_N23paixi_90040403_15_dialog_content = "I got it!",
  str_homestory_N23paixi_90040403_3_dialog_content = "Just a little more.",
  str_homestory_N23paixi_90040403_4_dialog_content = "I'll be waiting!",
  str_homestory_N23paixi_90040404_1_dialog_content = "You're so fast, PlayerName.",
  str_homestory_N23paixi_90040404_2_dialog_content = "All done. ({1}/{2})",
  str_homestory_N23paixi_90040404_5_dialog_content = "Wow! You're so cool, PlayerName!",
  str_homestory_N23paixi_90040404_6_dialog_content = "Now we have everything we need. I'm happy.",
  str_homestory_N23paixi_90040404_7_dialog_content = "Give me some time, PlayerName. I'll be sure to dazzle you with my work.",
  str_homestory_N23paixi_90040404_8_dialog_content = "You really don't need my help?",
  str_homestory_N23paixi_90040404_9_dialog_content = "You... really know how to make a mirror?",
  str_homestory_N23paixi_90040404_10_dialog_content = "I've taken on a job like this before. I had to pry off 31 mirrors.<sprite=emo_mojing size=60 />",
  str_homestory_N23paixi_90040404_11_dialog_content = "I can do this!",
  str_homestory_N23paixi_90040404_12_dialog_content = "All right... If you insist.",
  str_homestory_N23paixi_90040404_13_dialog_content = "Off you go, PlayerName! Leave me to my work!",
  str_homestory_N23paixi_90040404_14_dialog_content = "Okay...",
  str_homestory_N23paixi_90040404_3_dialog_content = "Just a little more.",
  str_homestory_N23paixi_90040404_4_dialog_content = "I'll be waiting!",
  str_homestory_N23paixi_90040405_1_dialog_content = "Heheh. PlayerName!",
  str_homestory_N23paixi_90040405_2_dialog_content = "Hey, Sadie!",
  str_homestory_N23paixi_90040405_3_dialog_content = "How are things going?",
  str_homestory_N23paixi_90040405_4_dialog_content = "Don't worry. I just wanted to see if you needed a hand.",
  str_homestory_N23paixi_90040405_5_dialog_content = "I'm already finished making the magic mirror!",
  str_homestory_N23paixi_90040405_6_dialog_content = "You'll see it in a bit.",
  str_homestory_N23paixi_90040405_7_dialog_content = "Really? So where is it?",
  str_homestory_N23paixi_90040405_8_dialog_content = "It's in my room. I have to polish it first before I can show it to you.",
  str_homestory_N23paixi_90040405_9_dialog_content = "All you need to do is to wait!",
  str_homestory_N23paixi_90040405_10_dialog_content = "Really? You're more capable than I imagined, Sadie.",
  str_homestory_N23paixi_90040405_11_dialog_content = "Hey!",
  str_homestory_N23paixi_90040405_12_dialog_content = "Ahem, I mean, you truly are capable!",
  str_homestory_N23paixi_90040405_13_dialog_content = "That's better.",
  str_homestory_N23paixi_90040406_1_dialog_content = "Helloooooo PlayerName!",
  str_homestory_N23paixi_90040406_2_dialog_content = "Did you get the prop? Did you did you did you?",
  str_homestory_N23paixi_90040406_3_dialog_content = "I got it got it got it.",
  str_homestory_N23paixi_90040406_4_dialog_content = "So, what was the prop that Sadie had in mind for the \"touching\" scene?",
  str_homestory_N23paixi_90040406_5_dialog_content = "I'm so curious!",
  str_homestory_N23paixi_90040406_6_dialog_content = "Turns out, the thing she kept going on about was a mirror.",
  str_homestory_N23paixi_90040406_7_dialog_content = "A mirror?",
  str_homestory_N23paixi_90040406_8_dialog_content = "Yeah. Quite frankly, I can't imagine actually shooting the scene she has in mind, but...",
  str_homestory_N23paixi_90040406_9_dialog_content = "As you put it, it wouldn't hurt to give it a shot.",
  str_homestory_N23paixi_90040406_10_dialog_content = "Yup!",
  str_homestory_N23paixi_90040406_11_dialog_content = "So, are you ready?",
  str_homestory_N23paixi_90040406_12_dialog_content = "We can start shooting our studio's very first movie!",
  str_homestory_N23paixi_90040406_13_dialog_content = "Yeah, I'm ready!",
  str_homestory_N23paixi_90040406_14_dialog_content = "Alright! Then...",
  str_homestory_N23paixi_90040406_15_dialog_content = "Now that we have our set, props, and equipment...",
  str_homestory_N23paixi_90040406_16_dialog_content = "We'll make up for everything else we lack with our passion!",
  str_homestory_N23paixi_90040406_17_dialog_content = "And now, let's get our female lead onto the scene! Sadie, the Swashbuckler!",
  str_homestory_N23paixi_90040406_18_dialog_content = "Ready! Everyone in position?",
  str_homestory_N23paixi_90040406_19_dialog_content = "Standby.",
  str_homestory_N23paixi_90040406_20_dialog_content = "Now, action!<sprite=emo_laba size=60 />",
  str_homestory_N23paixi_90040406_21_dialog_content = "The story...",
  str_homestory_N23paixi_90040406_22_dialog_content = "begins on a chilling, pitch-black night...",
  str_homestory_N23paixi_90040501_1_dialog_content = "PlayerName! Good timing! I have something that I wanted to ask you!",
  str_homestory_N23paixi_90040501_2_dialog_content = "What's up?",
  str_homestory_N23paixi_90040501_3_dialog_content = "You know how we just finished shooting The Swashbuckler?",
  str_homestory_N23paixi_90040501_4_dialog_content = "Did something happen? We already finished shooting though...",
  str_homestory_N23paixi_90040501_5_dialog_content = "Oh! Not at all. The movie's done. It's not about that!",
  str_homestory_N23paixi_90040501_6_dialog_content = "Phew, that's a relief.",
  str_homestory_N23paixi_90040501_7_dialog_content = "There's this older girl. I mean, she's not THAT old, but older than me at least.",
  str_homestory_N23paixi_90040501_8_dialog_content = "She's been hanging around the studio lately.",
  str_homestory_N23paixi_90040501_9_dialog_content = "But whenever I mean to approach her and ask if she wants to make a film,",
  str_homestory_N23paixi_90040501_10_dialog_content = "I feel this chilling aura emit from her and it scares me away.",
  str_homestory_N23paixi_90040501_11_dialog_content = "See! There she is!",
  str_homestory_N23paixi_90040501_12_dialog_content = "Oh, that's <color=#FFB400>Paloma</color>.",
  str_homestory_N23paixi_90040501_13_dialog_content = "Paloma. Somehow, that name sounds familiar.<sprite=emo_yaosu size=60 />",
  str_homestory_N23paixi_90040501_14_dialog_content = "Well, maybe it's because she also lived in Umbraton for a while?",
  str_homestory_N23paixi_90040501_15_dialog_content = "But many people live in Umbraton.",
  str_homestory_N23paixi_90040501_16_dialog_content = "Haha, I guess you're right.",
  str_homestory_N23paixi_90040501_17_dialog_content = "Hmph! You're just saying whatever, aren't you, PlayerName?",
  str_homestory_N23paixi_90040501_18_dialog_content = "Why don't you get over there and ask her why she's been hanging around the studio!",
  str_homestory_N23paixi_90040501_19_dialog_content = "My instincts tell me she wants to make a film but doesn't know how to tell us.",
  str_homestory_N23paixi_90040501_20_dialog_content = "Hmm, I'll go find out.",
  str_homestory_N23paixi_90040502_1_dialog_content = "PlayerName.",
  str_homestory_N23paixi_90040502_2_dialog_content = "Hey, Paloma.",
  str_homestory_N23paixi_90040502_3_dialog_content = "Hi.<sprite=emo_baiyan size=60 />",
  str_homestory_N23paixi_90040502_4_dialog_content = "Uhm... Ahem!",
  str_homestory_N23paixi_90040502_5_dialog_content = "Have you... developed an interest in the movie studio as of late?",
  str_homestory_N23paixi_90040502_6_dialog_content = "Yes. I heard that you could shoot anything you wanted here.",
  str_homestory_N23paixi_90040502_7_dialog_content = "That's right!",
  str_homestory_N23paixi_90040502_8_dialog_content = "Whether it's a documentary of your experiences, or a dream you want to realize, or someone else's story...",
  str_homestory_N23paixi_90040502_9_dialog_content = "The equipment in our studio can help you film anything!",
  str_homestory_N23paixi_90040502_10_dialog_content = "What do I need to do?",
  str_homestory_N23paixi_90040502_11_dialog_content = "Huh?",
  str_homestory_N23paixi_90040502_12_dialog_content = "Say I want to use the equipment here to document things that happen in real life and turn them into a film—",
  str_homestory_N23paixi_90040502_13_dialog_content = "Anyway, into something that serves as vivid documentation.",
  str_homestory_N23paixi_90040502_14_dialog_content = "If I want to do that, what do I have to give? What do you want from me?",
  str_homestory_N23paixi_90040502_15_dialog_content = "I can't imagine that you're running a charity here, after all.",
  str_homestory_N23paixi_90040502_16_dialog_content = "Ahem. Well, if you're asking me how much it costs... It's free.",
  str_homestory_N23paixi_90040502_17_dialog_content = "For now, at least!",
  str_homestory_N23paixi_90040502_18_dialog_content = "As for the future...",
  str_homestory_N23paixi_90040502_19_dialog_content = "We'll decide if we want to charge outside Cloud Gardens once we get a handle on the operations...",
  str_homestory_N23paixi_90040502_20_dialog_content = "Mm... we'll think about that stuff later.",
  str_homestory_N23paixi_90040502_21_dialog_content = "All you have to know is that for now, our studio is free!",
  str_homestory_N23paixi_90040502_22_dialog_content = "Oh?",
  str_homestory_N23paixi_90040502_23_dialog_content = "To put it simply, if there's a film that you want to make, all you have to do is to submit the script and props to us.",
  str_homestory_N23paixi_90040502_24_dialog_content = "Of course, if you don't have the necessary props, I can help gather materials to make them.",
  str_homestory_N23paixi_90040502_25_dialog_content = "Or, if you don't know how to write a script... I can also try to...",
  str_homestory_N23paixi_90040502_26_dialog_content = "You know... help gather some inspiration... or something.",
  str_homestory_N23paixi_90040502_27_dialog_content = "You mean I don't have to lift a finger?",
  str_homestory_N23paixi_90040502_28_dialog_content = "I-Is that what I just said?",
  str_homestory_N23paixi_90040502_29_dialog_content = "Isn't that basically what you're saying?",
  str_homestory_N23paixi_90040502_30_dialog_content = "I...",
  str_homestory_N23paixi_90040502_31_dialog_content = "I'm just kidding.",
  str_homestory_N23paixi_90040502_32_dialog_content = "I... really can't tell by the seriousness on your face.",
  str_homestory_N23paixi_90040502_33_dialog_content = "I have a script ready.",
  str_homestory_N23paixi_90040502_34_dialog_content = "What I do need is inspiration, preferably things that are true to life and believable.",
  str_homestory_N23paixi_90040502_35_dialog_content = "Strictly speaking, the film that I want to make... should be something like a documentary.",
  str_homestory_N23paixi_90040502_36_dialog_content = "A documentary?",
  str_homestory_N23paixi_90040502_37_dialog_content = "Yeah.",
  str_homestory_N23paixi_90040502_38_dialog_content = "I see...",
  str_homestory_N23paixi_90040502_39_dialog_content = "Alright, understood.",
  str_homestory_N23paixi_90040502_40_dialog_content = "Don't worry. I've done this before!",
  str_homestory_N23paixi_90040502_41_dialog_content = "So, whose daily life do you want me to research as your inspiration?",
  str_homestory_N23paixi_90040502_42_dialog_content = "<color=#FFB400>Sikare.</color>",
  str_homestory_N23paixi_90040502_43_dialog_content = "... S-Sikare!?",
  str_homestory_N23paixi_90040502_44_dialog_content = "Is there a problem? People of different professions surely lead different lives.",
  str_homestory_N23paixi_90040502_45_dialog_content = "N-No problem...",
  str_homestory_N23paixi_90040502_46_dialog_content = "And obviously, you are closer to her than I am.",
  str_homestory_N23paixi_90040502_47_dialog_content = "That's why you're better for the job.",
  str_homestory_N23paixi_90040502_48_dialog_content = "Alright, understood.",
  str_homestory_N23paixi_90040502_49_dialog_content = "Thank you.",
  str_homestory_N23paixi_90040502_50_dialog_content = "I'll be waiting here.",
  str_homestory_N23paixi_90040503_1_dialog_content = "Snowball?",
  str_homestory_N23paixi_90040503_2_dialog_content = "Hey, Sikare.",
  str_homestory_N23paixi_90040503_3_dialog_content = "Long time no see.",
  str_homestory_N23paixi_90040503_4_dialog_content = "The idiotic but happy life of those paramecia got to you too, huh?",
  str_homestory_N23paixi_90040503_5_dialog_content = "I...",
  str_homestory_N23paixi_90040503_6_dialog_content = "I have no idea how to respond to that.",
  str_homestory_N23paixi_90040503_7_dialog_content = "I understand. You share \"friendship bonds\" with them.",
  str_homestory_N23paixi_90040503_8_dialog_content = "So, why are you here?",
  str_homestory_N23paixi_90040503_9_dialog_content = "Snowball, you really are special, unlike that lot.",
  str_homestory_N23paixi_90040503_10_dialog_content = "I have no desire to even speak to them at all. I can't stand the smell of paramecia on them.",
  str_homestory_N23paixi_90040503_11_dialog_content = "Right... Let me be frank, Sikare.",
  str_homestory_N23paixi_90040503_12_dialog_content = "Paloma wants me to ask you what your day to day life is like.",
  str_homestory_N23paixi_90040503_13_dialog_content = "Please don't misunderstand! She just wants to make a documentary about the daily lives of all kinds of people.",
  str_homestory_N23paixi_90040503_14_dialog_content = "So... she asked me to find out about yours.",
  str_homestory_N23paixi_90040503_15_dialog_content = "Paloma... I know who she is.",
  str_homestory_N23paixi_90040503_16_dialog_content = "We've met. Just a few times, though.",
  str_homestory_N23paixi_90040503_17_dialog_content = "Looks like she's just a little smarter than the rest of the paramecia.",
  str_homestory_N23paixi_90040503_18_dialog_content = "At the very least, she was smart enough to know that she'd get her answers if she sent you.",
  str_homestory_N23paixi_90040503_19_dialog_content = "But keep this in mind, Snowball.",
  str_homestory_N23paixi_90040503_20_dialog_content = "The only reason I'm answering her questions is because you're the one who's asking me.",
  str_homestory_N23paixi_90040503_21_dialog_content = "Right. Thanks, Sikare.",
  str_homestory_N23paixi_90040503_22_dialog_content = "I begin my days by conversing with Faria.",
  str_homestory_N23paixi_90040503_23_dialog_content = "If I'm in a good mood, I do nothing but gaze up at the peaceful sky.<sprite=emo_pugongying size=60 />",
  str_homestory_N23paixi_90040503_24_dialog_content = "If I'm in a bad mood... then the sky here isn't able to satisfy me.",
  str_homestory_N23paixi_90040503_25_dialog_content = "Then I go where I belong and tell Faria about stories I've heard.",
  str_homestory_N23paixi_90040503_26_dialog_content = "About the outside world, about the sky that changes color, the trees that shed their leaves, and...",
  str_homestory_N23paixi_90040503_27_dialog_content = "People that walk the earth.",
  str_homestory_N23paixi_90040503_28_dialog_content = "That's what my days are like.",
  str_homestory_N23paixi_90040503_29_dialog_content = "I'll be sure to let Paloma know.",
  str_homestory_N23paixi_90040503_30_dialog_content = "I think she'll be satisfied with this answer.",
  str_homestory_N23paixi_90040503_31_dialog_content = "Huh?",
  str_homestory_N23paixi_90040503_32_dialog_content = "You're not gonna give me the same pitiful look that all the other paramecia do?",
  str_homestory_N23paixi_90040503_33_dialog_content = "I wouldn't look at you like that.",
  str_homestory_N23paixi_90040503_34_dialog_content = "To quote Paloma...",
  str_homestory_N23paixi_90040503_35_dialog_content = "\"People of different professions surely lead different lives.\"",
  str_homestory_N23paixi_90040503_36_dialog_content = "So, if this is what your day is like and if you're unable to change it, then I wish for you to be happy every day.",
  str_homestory_N23paixi_90040503_37_dialog_content = "...",
  str_homestory_N23paixi_90040503_38_dialog_content = "You certainly are different from the others, Snowball.",
  str_homestory_N23paixi_90040504_1_dialog_content = "PlayerName.",
  str_homestory_N23paixi_90040504_2_dialog_content = "Hm...",
  str_homestory_N23paixi_90040504_3_dialog_content = "...",
  str_homestory_N23paixi_90040504_4_dialog_content = "... So that's what Sikare's days are like.",
  str_homestory_N23paixi_90040504_5_dialog_content = "I see.",
  str_homestory_N23paixi_90040504_6_dialog_content = "Thank you for helping me with the research.",
  str_homestory_N23paixi_90040504_7_dialog_content = "I'll be sure to use it in my script.",
  str_homestory_N23paixi_90040504_8_dialog_content = "You'll have it soon enough, along with the props I've prepared.",
  str_homestory_N23paixi_90040504_9_dialog_content = "Okay.",
  str_homestory_N23paixi_90040504_10_dialog_content = "And after that... I'll leave my documentary in your capable hands.",
  str_homestory_N23paixi_90040504_11_dialog_content = "Right! No problem!",
  str_homestory_N23paixi_90040504_12_dialog_content = "Thanks, PlayerName.",
  str_homestory_N23paixi_90040505_1_dialog_content = "Hey, PlayerName. How did it go?",
  str_homestory_N23paixi_90040505_2_dialog_content = "Well, you were right.",
  str_homestory_N23paixi_90040505_3_dialog_content = "Paloma did want to make a film.",
  str_homestory_N23paixi_90040505_4_dialog_content = "But she needed special inspirational material, so I helped her out.",
  str_homestory_N23paixi_90040505_5_dialog_content = "Wow!",
  str_homestory_N23paixi_90040505_6_dialog_content = "But all that's done now!",
  str_homestory_N23paixi_90040505_7_dialog_content = "Her script is done too.",
  str_homestory_N23paixi_90040505_8_dialog_content = "She even said that she was gonna provide us with the props.",
  str_homestory_N23paixi_90040505_9_dialog_content = "Wow!!",
  str_homestory_N23paixi_90040505_10_dialog_content = "She must be rich!<sprite=emo_baiyebi size=60 />",
  str_homestory_N23paixi_90040505_11_dialog_content = "I don't really know about that.",
  str_homestory_N23paixi_90040505_12_dialog_content = "But she couldn't be poorer than the two of us.",
  str_homestory_N23paixi_90040505_13_dialog_content = "I'm so jealous!",
  str_homestory_N23paixi_90040505_14_dialog_content = "Well anyway, I'm all fired up now!",
  str_homestory_N23paixi_90040505_15_dialog_content = "I'm gonna acquire all kinds of skills and make a lot of money with my own abilities!",
  str_homestory_N23paixi_90040505_16_dialog_content = "PlayerName, let's get the camera rolling once we get the props.",
  str_homestory_N23paixi_90040505_17_dialog_content = "Got it!",
  str_homestory_N23paixi_90040601_1_dialog_content = "My dearest friend!",
  str_homestory_N23paixi_90040601_2_dialog_content = "Charon!",
  str_homestory_N23paixi_90040601_3_dialog_content = "You also want to make a film?",
  str_homestory_N23paixi_90040601_4_dialog_content = "A film?",
  str_homestory_N23paixi_90040601_5_dialog_content = "No, no, no, PlayerName.",
  str_homestory_N23paixi_90040601_6_dialog_content = "I was just admiring the record player here.<sprite=emo_yinfu size=60 />",
  str_homestory_N23paixi_90040601_7_dialog_content = "Right. I remember you were a fan of that.",
  str_homestory_N23paixi_90040601_8_dialog_content = "Once.",
  str_homestory_N23paixi_90040601_9_dialog_content = "I once regarded that record player as my favorite thing in the world!",
  str_homestory_N23paixi_90040601_10_dialog_content = "Huh?",
  str_homestory_N23paixi_90040601_11_dialog_content = "Wait. Does that mean you've fallen in love with another record player?",
  str_homestory_N23paixi_90040601_12_dialog_content = "Not at all, my dear friend.",
  str_homestory_N23paixi_90040601_13_dialog_content = "I am a very loyal person.",
  str_homestory_N23paixi_90040601_14_dialog_content = "That said, I do believe that record player could use some improvements.",
  str_homestory_N23paixi_90040601_15_dialog_content = "What do you mean?",
  str_homestory_N23paixi_90040601_16_dialog_content = "You've built a new arts center here. That charming structure could hardly escape my eye.",
  str_homestory_N23paixi_90040601_17_dialog_content = "But it got me thinking about the other work of art in Cloud Gardens—the record player, that is. It could really use an update.",
  str_homestory_N23paixi_90040601_18_dialog_content = "Oh! Music and films!",
  str_homestory_N23paixi_90040601_19_dialog_content = "Only when they are combined can they grace this place with the most glamorous light!",
  str_homestory_N23paixi_90040601_20_dialog_content = "Uhm... Okay, I can see your reasoning behind that.",
  str_homestory_N23paixi_90040601_21_dialog_content = "But I don't really know much about music. How do you think we should improve the record player?",
  str_homestory_N23paixi_90040601_22_dialog_content = "My friend, nothing pleasures me more than answering this question of yours.",
  str_homestory_N23paixi_90040601_23_dialog_content = "Adjustments can be made to make its cogs work more precisely, making the music sound even better...",
  str_homestory_N23paixi_90040601_24_dialog_content = "Oh, the mere thought of it excites me!<sprite=emo_aixin size=60 />",
  str_homestory_N23paixi_90040601_25_dialog_content = "Would you elaborate more on that?",
  str_homestory_N23paixi_90040601_26_dialog_content = "I see you're just as excited as I am!",
  str_homestory_N23paixi_90040601_27_dialog_content = "Good! Then let's not waste any more time!",
  str_homestory_N23paixi_90040601_28_dialog_content = "Of course, you can leave adjustments to me.",
  str_homestory_N23paixi_90040601_29_dialog_content = "But I will need you to take care of something small.",
  str_homestory_N23paixi_90040601_30_dialog_content = "First, I'll need some water.",
  str_homestory_N23paixi_90040601_31_dialog_content = "We need to <color=#FFB400>tidy up the record player's surroundings</color>.",
  str_homestory_N23paixi_90040601_32_dialog_content = "That way, it can return to its old radiant self in the embrace of a clean environment.",
  str_homestory_N23paixi_90040601_33_dialog_content = "Sure, no problem.",
  str_homestory_N23paixi_90040601_34_dialog_content = "Then, I shall take the time to study that beautiful record player...",
  str_homestory_N23paixi_90040601_35_dialog_content = "and ponder on how to make it even more radiant.",
  str_homestory_N23paixi_90040602_1_dialog_content = "I know you'd never let an artist down.",
  str_homestory_N23paixi_90040602_2_dialog_content = "That's right. ({1}/{2})",
  str_homestory_N23paixi_90040602_5_dialog_content = "Excellent.",
  str_homestory_N23paixi_90040602_6_dialog_content = "Now that we have water, we can tidy up the record player's surroundings.",
  str_homestory_N23paixi_90040602_7_dialog_content = "Yup!",
  str_homestory_N23paixi_90040602_8_dialog_content = "I'll take the outer area. I'll leave the area near the record player to you, alright?",
  str_homestory_N23paixi_90040602_9_dialog_content = "Actually, why don't you leave all the cleaning to me, my dearest friend?",
  str_homestory_N23paixi_90040602_10_dialog_content = "Huh? Why?",
  str_homestory_N23paixi_90040602_11_dialog_content = "I believe the record player needs some polishing for it to exude all its alluring and glamorous beauty.",
  str_homestory_N23paixi_90040602_12_dialog_content = "I think we'll need some <color=#FFB400>ore</color>.",
  str_homestory_N23paixi_90040602_13_dialog_content = "You want to polish the record player with ore?",
  str_homestory_N23paixi_90040602_14_dialog_content = "That's right, my dear friend.",
  str_homestory_N23paixi_90040602_15_dialog_content = "I have no idea what you're thinking, but then again, I can't find any fault with it either.",
  str_homestory_N23paixi_90040602_16_dialog_content = "Oh I promise, you will understand once you see the results.",
  str_homestory_N23paixi_90040602_17_dialog_content = "All right. I trust you.",
  str_homestory_N23paixi_90040602_18_dialog_content = "The surrounding environment of the record player has been cleaned... but it is far from enough!",
  str_homestory_N23paixi_90040602_19_dialog_content = "It's still some distance from achieving the shining ultimate goal.",
  str_homestory_N23paixi_90040602_20_dialog_content = "Yep.",
  str_homestory_N23paixi_90040602_3_dialog_content = "Just a moment...",
  str_homestory_N23paixi_90040602_4_dialog_content = "Right. I shall wait here in anticipation a little longer, then.",
  str_homestory_N23paixi_90040603_1_dialog_content = "I know you won't let an artist down.",
  str_homestory_N23paixi_90040603_2_dialog_content = "That's right. ({1}/{2})",
  str_homestory_N23paixi_90040603_5_dialog_content = "Good.",
  str_homestory_N23paixi_90040603_6_dialog_content = "The materials are all ready!",
  str_homestory_N23paixi_90040603_7_dialog_content = "Dearest friend, I must thank you very much for supporting my dream.",
  str_homestory_N23paixi_90040603_8_dialog_content = "Is this it?",
  str_homestory_N23paixi_90040603_9_dialog_content = "Yes.",
  str_homestory_N23paixi_90040603_10_dialog_content = "While you've been busy helping me achieve my dream, I've come up with how we can update that beautiful record player.",
  str_homestory_N23paixi_90040603_11_dialog_content = "All you have to do now is wait.",
  str_homestory_N23paixi_90040603_12_dialog_content = "Alright then.",
  str_homestory_N23paixi_90040603_13_dialog_content = "Thanks, Charon!",
  str_homestory_N23paixi_90040603_14_dialog_content = "It is I who should be thanking you.",
  str_homestory_N23paixi_90040603_3_dialog_content = "Wait a second...",
  str_homestory_N23paixi_90040603_4_dialog_content = "Ah, I shall wait here in anticipation a little longer, then.",
  str_homestory_N23paixi_90040604_1_dialog_content = "Whoa, PlayerName!",
  str_homestory_N23paixi_90040604_2_dialog_content = "A lot of Aurorians have been to our movie studio!",
  str_homestory_N23paixi_90040604_3_dialog_content = "Yeah! Vice, have you seen the films they made?",
  str_homestory_N23paixi_90040604_4_dialog_content = "Wait. You mean they weren't just touring the place, but that they actually made films?",
  str_homestory_N23paixi_90040604_5_dialog_content = "That's right!",
  str_homestory_N23paixi_90040604_6_dialog_content = "That's amazing, PlayerName!",
  str_homestory_N23paixi_90040604_7_dialog_content = "Hahaha. Well, it was your idea, so I can't take all the credit.",
  str_homestory_N23paixi_90040604_8_dialog_content = "It's a bit egoistic to compliment oneself, but I still have to say: See, I told you so!",
  str_homestory_N23paixi_90040604_9_dialog_content = "Everyone has experiences they want to document visually!",
  str_homestory_N23paixi_90040604_10_dialog_content = "You're right.",
  str_homestory_N23paixi_90040604_11_dialog_content = "Ah, but on that note...",
  str_homestory_N23paixi_90040604_12_dialog_content = "You've been hard at work, haven't you?",
